// strings.ts: English defaults (fallback + key typing) for UI keys only
const ui = Object.entries(S).filter(([k]) => !/^[A-Z]/.test(k));
const ts = `// Generated from the same table as strings/*.resx. English fallbacks; translations live in the resx files.
export const defaultStrings = {
${ui.map(([k, v]) => `    ${k}: ${JSON.stringify(v[0])},`).join("\n")}
};

export type StringKey = keyof typeof defaultStrings;
`;
writeFileSync(join(dir, "model", "strings.ts"), ts, "utf8");
console.log(`Wrote ${Object.keys(S).length} strings (${ui.length} UI) in 3 languages.`);
